<section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold text-slate-900">Atualizar localização</h2><form method="POST" action="{{ route('tickets.location',$ticket) }}" class="mt-4 space-y-3">@csrf @method('PATCH')<label class="block text-xs font-medium text-slate-500">Campus<select name="campus_id" required class="mt-1 w-full rounded-xl border-slate-200 text-sm">@foreach(\App\Models\Campus::where('is_active',true)->orderBy('name')->get() as $campus)<option value="{{ $campus->id }}" @selected($ticket->campus_id===$campus->id)>{{ $campus->name }}</option>@endforeach</select></label><label class="block text-xs font-medium text-slate-500">Prédio<select name="building_id" class="mt-1 w-full rounded-xl border-slate-200 text-sm"><option value="">Sem prédio</option>@foreach(\App\Models\Building::where('is_active',true)->orderBy('name')->get() as $building)<option value="{{ $building->id }}" @selected($ticket->building_id===$building->id)>{{ $building->campus->name }} · {{ $building->name }}</option>@endforeach</select></label><label class="block text-xs font-medium text-slate-500">Local<select name="location_id" class="mt-1 w-full rounded-xl border-slate-200 text-sm"><option value="">Sem local</option>@foreach(\App\Models\Location::where('is_active',true)->orderBy('name')->get() as $location)<option value="{{ $location->id }}" @selected($ticket->location_id===$location->id)>{{ $location->building->name }} · {{ $location->name }}</option>@endforeach</select></label><label class="block text-xs font-medium text-slate-500">Detalhes<input name="location_details" maxlength="2000" value="{{ $ticket->location_details }}" class="mt-1 w-full rounded-xl border-slate-200 text-sm"></label><button class="w-full rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-700">Salvar localização</button></form></section>
